const html = 'public/index.html';
const openai = 'public/scripts/openai.js';

export default [
    { id: 'recovery.import-new-instance', title: 'Importing foreign chats as a new instance', keys: ['Import as new instance', 'Import from another instance', 'ROLEPLAY_IMPORT_ORIGIN_CHANGED', 'adopt chat', 'foreign chat import'], sources: [html, 'public/script.js', 'src/roleplay-lifecycle.js'], anchors: ['Import as new instance', 'Bring your chats too', 'ROLEPLAY_IMPORT_ORIGIN_CHANGED'],
        content: 'To adopt chat files from another Neconyan instance, select a character first. Characters → Import → Bring your chats too offers Import as new instance; Past chats also offers it under Import from another instance. Tick it before choosing files through Import Chat. It creates a separate copy of the selected character and chats, even if names match, without merging existing history. The new copy has no continuity link to its source. Leave it off for normal origin and seal checks. ROLEPLAY_IMPORT_ORIGIN_CHANGED means the recorded origin or integrity check does not match; adopting a new copy is an explicit choice, not an automatic repair. Group-chat adoption must go through a selected character\'s import option. Ordinary saved-file protections apply to the new copy afterwards.' },
    { id: 'recovery.transferred-data', title: 'Repairing chats after manually copying folders', keys: ['Repair transferred data', 'Check transferred data', 'Back up and repair', 'copied chats', 'missing chats after reload', 'Termux chats disappeared', 'ROLEPLAY_SOURCE_CHANGED', 'ROLEPLAY_FOREIGN_SOURCE', 'removed _roleplay', 'chat tracking records', 'corrupt chats', 'unreadable chat', 'repair leave out', 'Termux identity repair', 'stable file identity', 'Termux startup stops'], sources: ['public/scripts/roleplay-recovery-ui.js', 'src/roleplay-transfer-recovery.js', 'src/generation/roleplay-source.js', 'docs/data-portability.md', 'scripts/repair-data-identity.js'], anchors: ['Repair transferred data', 'Check transferred data', 'Back up and repair', 'Reload repaired account', 'ROLEPLAY_RECOVERY_CHANGED', 'repair-data-identity.js'],
        content: 'Startup reconnects unchanged tracked files after a complete stopped-folder move. Changed or missing files can still need repair. ROLEPLAY_SOURCE_CHANGED reports a mismatch; ROLEPLAY_FOREIGN_SOURCE can follow removing tracking records. If an older Termux folder cannot safely use its file-identity policy, stop every server and follow the offline check, backup, apply and resume instructions in docs/data-portability.md on the affected Termux installation. This affects all accounts and requires a separate backup. Otherwise, if the app opens, use Settings → System & Device → Import & Restore → Repair transferred data. Press Check transferred data, review the report, then Back up and repair. This backs up chats, cards, groups and tracking, accepts valid files on disk and invalidates earlier accepted work. Unreadable chats or cards and names ending in a space or full stop are left out and listed; broken groups block repair. Missing or corrupt content cannot be reconstructed. Use Reload repaired account afterwards. If identity or ledger files are unreadable, preserve the folder and restore a known complete stopped snapshot. Keep tracking records and chat markers intact rather than deleting them by hand.' },
    { id: 'recovery.data-portability', title: 'Moving one data folder between devices', keys: ['move data folder', 'sync data folder', 'dual boot', 'external drive', 'machine IDs', 'phone as master', 'Android APK desktop access', 'one copy multiple devices', 'stopped folder', 'Git data sync', 'GitHub sync', 'GitHub folder sync'], sources: ['docs/data-portability.md', 'src/roleplay-transfer-recovery.js', 'src/roleplay-lifecycle.js', 'android/server-bootstrap.mjs'], anchors: ['Taking a stopped folder elsewhere', 'Sync a data folder with GitHub', '127.0.0.1'],
        content: 'One reachable server can serve several screens. Away from home use authenticated HTTPS or a private network. The Android APK only accepts connections from its own phone. For offline moves, finish work and stop both servers; transfer account data and tracking, preserving their identities and saved history. Leave the device-local ownership lock behind. Machine IDs do not resolve conflicting edits. There is no automatic multi-writer sync. For private GitHub sync, disable line-ending conversion before checkout, commit and push the stopped source, then pull with --ff-only before starting the destination. Never hand-merge protected ledgers; keep both conflicting copies and a separate backup. The repository can contain API keys, so review staged files and keep it private. See docs/data-portability.md for Termux worktrees and repair.' },
    { id: 'recovery.pending-operation', title: 'An unfinished Roleplay operation blocks chats', keys: ['ROLEPLAY_RECOVERY_REQUIRED', 'earlier Roleplay transaction', 'must be reconciled first', 'unfinished Roleplay operation', 'cannot create chats'], sources: ['src/generation/roleplay-source.js', 'src/roleplay-lifecycle.js', 'src/server-main.js', 'public/scripts/roleplay-recovery-ui.js'], anchors: ['An earlier Roleplay transaction must be reconciled first.', 'bootstrapRoleplayAccount', 'needs recovery; its protected writes stay refused.'],
        content: 'ROLEPLAY_RECOVERY_REQUIRED means an earlier account operation has not finished; it can block both individual and group chats and new saves. Restarting the Neconyan server runs built-in reconciliation, which attempts to finish that recorded operation. Refreshing the browser alone does not run startup recovery. If it still fails, get the first startup error after the Roleplay storage needs recovery message, rather than only repeated chat-load errors. After a manual transfer, Settings → System & Device → Import & Restore → Repair transferred data offers Check transferred data, then Back up and repair. This archives the unfinished operation and accepts the files currently on disk; it does not promise to complete the old write. Review the report and use Reload repaired account after success. Preserve the files and tracking directory; clearing tracking by hand can leave old chats unreadable. This error alone does not prove chat files were deleted.' },
    { id: 'recovery.selective-import', title: 'Importing only chats, personas, character cards or lorebooks', keys: ['Choose what to import', 'Import Folder', 'Import Backup ZIP', 'import only chats', 'import only personas', 'import only character cards', 'import only lorebooks', 'SillyBunny import', 'SillyTavern folder path'], sources: ['public/scripts/neconyan-tabs.js', 'public/scripts/account-import.js', 'src/operations/import-personas.js', 'src/operations/import-inputs.js', 'src/operations/import-content-policy.js'], anchors: ['Choose what to import', 'Import From Folder Path', 'Download skipped-files report'],
        content: 'Settings → System & Device → Import & Restore → Choose what to import offers Chats, Personas, Character cards and Lorebooks, all initially ticked. Keep at least one. Chats include groups and attachments; Personas imports avatars and merges only persona names/descriptions from settings.json. Lorebooks includes native books from the worlds folder and their saved history, retaining names, contents and metadata. For Import Folder, provide an installation, data or user folder accessible to the Neconyan server, not a path on a separate phone or computer. Otherwise choose Import Backup ZIP with a SillyTavern or SillyBunny account backup. Matching selected-library files are replaced; other preferences, API keys, presets and themes stay unchanged. Sync Extensions is separate. Read the completion report before reloading: intentional exclusions and damaged files are listed separately, with Download skipped-files report for the full list. Use Reload imported account when finished. This does not restore every setting from the old app.' },
    { id: 'connections.current-model', title: 'The current model in the top bar', keys: ['Current Model', 'model in top bar', 'Short Model Name', 'model label'], sources: ['public/scripts/neconyan-tabs.js'], anchors: ['Current Model', 'Short Model Name'],
        content: 'The top-bar Current Model item shows the model selected in Connections. Its label follows Short Model Name in Appearance → Visual Toggles. It identifies the main selected model, not necessarily the saved profile used by Conversation, an Agent or Mewmory. If a helper uses a different model, check that helper\'s connection profile rather than assuming the top-bar label describes every request.' },
    { id: 'recovery.damaged-import', title: 'Damaged files skipped during account import', keys: ['damaged import', 'skipped files', 'corrupt backup', 'import report', 'damaged backup'], sources: ['public/scripts/account-import.js', 'public/scripts/neconyan-tabs.js', 'src/operations/import-batches.js'], anchors: ['Reload to use the imported data', 'Other selected files were imported.'],
        content: 'Choose chats, personas, character cards and lorebooks separately before a folder or backup ZIP import; all four are ticked by default. Chats include group chats, group definitions and attachments. Personas include avatar images, names and descriptions; only those libraries are read from settings.json, so other account preferences stay as they are. Lorebooks includes native books and saved history. Damaged lorebook files are skipped without replacing existing copies; other selected files continue importing. Unselected library files, presets, themes, extensions, keys and bookkeeping files are left out on purpose and listed separately from damaged files. The report names files and gives reasons, stays on screen until Reload to use the imported data, and offers Download skipped-files report for the full deliberate-exclusion list. To recover a damaged item, re-export it from the original app and import it again. Saved account imports reopen the same report. A completely unreadable archive or another fatal import error still needs its own diagnosis; this is not a promise that every damaged ZIP can be recovered.' },
    { id: 'connections.setup', title: 'Connecting a text model', keys: ['Connections', 'API key', 'endpoint', 'connect model', 'provider', 'no model'], covers: ['core:connections'], sources: ['public/scripts/neconyan-native-workspaces.js', openai],
        content: 'Open Connections, choose the supported connection/API type and provider, enter its endpoint and credentials where required, then select a model and connect. Local services must be reachable from the component making the request; localhost on a hosted server refers to that server, not your phone. Use the provider\'s documented endpoint format. Neconyan does not supply provider credits. Keep credentials in the connection controls, not in character cards or chat messages.' },
    { id: 'connections.profiles', title: 'Saved connection profiles', keys: ['Connection Profiles', 'saved connection', 'save profile', 'reload profile', 'connection manager'], covers: ['extension:connection-manager'], sources: ['public/scripts/extensions/connection-manager/settings.html', 'public/scripts/extensions/shared.js'],
        content: 'Saved connections/Connection Profiles lets you create a New profile, Save (update) it, view Details, Edit, Reload or Delete it, and organise profiles with Folders and Favourite. A profile combines connection choices and associated presets; it is not just a provider key. Saving records the current configuration, while Reload reapplies the saved profile. Helpers such as Agents, Conversation and Mewmory may explicitly choose a different saved profile from the main reply writer.' },
    { id: 'connections.proxy-confirmation', title: 'Confirming a profile or preset proxy address', keys: ['Connecting To Proxy', 'confirm proxy address', 'profile proxy not saved', 'preset proxy', 'reverse proxy confirmation', 'proxy approval', 'No further proxy question'],
        sources: ['public/scripts/openai.js', 'public/scripts/extensions/shared.js', 'public/scripts/extensions/connection-manager/index.js'], anchors: ['Connecting To Proxy', 'Connection profile not saved. Confirm its proxy address to save it.', 'Preset not saved. Confirm its proxy address to save it.', 'Preset not imported. Import it again and confirm its proxy address, or remove the proxy fields.'],
        content: 'When a connection profile or a Chat Completion preset carries a reverse proxy, Neconyan asks Connecting To Proxy once for that address when you create or update the profile, save or update the preset, or import a preset with one. Choose No and the profile is not saved, or the preset is not saved or imported, with a message saying why; for a profile it reads Connection profile not saved. Confirm its proxy address to save it. An address you have already confirmed anywhere is not asked about again. Requests also check the proxy they actually send, so a profile saved before this change asks once on its first request and is then remembered. A preset saves exactly the address you approved, even if the field changes while the question is open. If another update changes a profile while the confirmation is open, the newer values are kept and you are asked to try again. Declining a proxy for an agent or tool does not mark your main connection as offline.' },
    { id: 'connections.model-search', title: 'Searching and grouping model lists', keys: ['search models', 'filter models', 'find model', 'model list too long', 'model dropdown', 'model groups', 'favourite model'], sources: ['public/scripts/model-list-search.js', 'public/scripts/model-family.js', openai], anchors: ['Search by name or model ID…', 'Favourites'],
        content: 'Every chat and text-completion backend with a single model choice shows its models as a list of buttons with a Search by name or model ID… box above it, on phones and desktop. Search matches every word you type against the name and ID, ignoring case; Escape clears it, and Enter picks the first match. Tapping a model selects it straight away and does not open the keyboard. Starred models sit in a Favourites group with a star at the right edge. Other models are grouped by family worked out from their IDs, so a new release such as gemini-3.5-flash joins the Gemini 3.5 group without an update; OpenRouter and ElectronHub keep their own vendor grouping when it is switched on. Lists show every available model, including NanoGPT and OpenRouter; scroll to browse the full catalogue without searching. NanoGPT names start with their source, such as Google/Gemma 4 31B, because it hosts the same model from several organisations. Searching only changes the view: it saves nothing and makes no model request.' },
    { id: 'connections.model-rotation', title: 'Random model rotation', keys: ['Random model rotation', 'rotate models', 'random model', 'different model each reply', 'model roulette'], sources: ['public/scripts/neconyan-model-rotation.js', 'public/scripts/neconyan-native-workspaces.js'], anchors: ['Random model rotation', 'Rotate models on every reply and swipe'],
        content: 'Connections → Saved connections has a Random model rotation panel. Tick Rotate models on every reply and swipe, then tick the saved connection profiles to include. Before each reply or swipe, Neconyan applies one ticked profile at random, exactly as if you picked it by hand, and skips the previous one while another remains. Quiet and helper requests do not rotate. It needs saved connection profiles first and does not add requests; each reply still costs whatever its chosen provider charges. The applied profile stays selected afterwards.' },
    { id: 'connections.custom-endpoint', title: 'Custom endpoint profiles and Additional Parameters', keys: ['Custom Endpoint Profiles', 'custom endpoint', 'OpenAI-compatible', 'Additional Parameters', 'extra body parameters', 'custom headers', 'Reasoning Parameter'], sources: [html, 'public/scripts/templates/customEndpointAdditionalParameters.html', 'public/scripts/openai-preset-utils.js'], anchors: ['Custom Endpoint Profiles', 'Saved Custom OpenAI-compatible URLs, API keys, and model IDs.', 'Reasoning Parameter'],
        content: 'For the Custom (OpenAI-compatible) source, Custom Endpoint Profiles saves a Profile Name with its base URL, API key and model ID; use the save and trash buttons beside the list. Additional Parameters opens a popup with Include Body Parameters (name: value per line), Exclude Body Parameters (one dash-prefixed key per line), Include Request Headers (an Authorization header replaces the saved key) and Reasoning Parameter, whose Parameter Format sends your Reasoning Effort as an OpenAI effort string, boolean, enabled/disabled string or thinking object. Endpoint profiles store only URL, key and model, not these parameters.' },
    { id: 'connections.presets', title: 'Model presets and prompt formatting', keys: ['model preset', 'generation preset', 'instruct template', 'context template', 'system prompt', 'prompt order'], covers: ['core:presets'], sources: ['public/scripts/preset-manager.js', openai, 'public/scripts/instruct-mode.js'],
        content: 'Model presets store generation/prompt settings for the applicable API. Text-completion instruct/context templates format roles and separators; Chat Completion sends structured messages and uses its prompt ordering controls. Match formatting to the model/provider rather than assuming one template suits all. Saving a model preset is different from saving a connection profile, UI theme, agent setup or image configuration. Inspect the final prompt after major formatting changes.' },
    { id: 'connections.preset-tour', title: 'Nori’s Presets tour and saving a writing setup', keys: ['Presets tour', 'Nori preset tour', 'save writing setup', 'Update current preset', 'Save preset as', 'Rename current preset', 'Switching Presets', 'Preset API/Sampler Linking'], sources: ['public/scripts/neconyan-tool-tour.js', 'public/scripts/preset-manager.js', 'public/scripts/neconyan-native-workspaces.js'], anchors: ['Saved writing setup', 'Update current preset', 'Switching Presets', 'Keep API/model linked to preset', 'Keep sampling settings linked to preset'],
        content: 'Open Fine-tuning → Presets and use Tour for Nori\'s walkthrough. The page follows the reply format selected in Connections. Update current preset overwrites the selected preset; Save preset as with a new name keeps the original; Rename current preset changes its name without duplicating it. Import and Export transfer presets for that reply format. Parameters covers token budget and output length, and its last section, Switching Presets (formerly Preset API/Sampler Linking), holds Keep API/model linked to preset, Keep sampling settings linked to preset and Remember sampling settings per model for Chat Completion; Sampling has its own page. Prompts controls entries and order. Text-completion templates are in Formatting. Loading a preset can replace current writing settings, not saved chat messages. The tour itself opens and explains controls without saving, deleting or making model requests.' },
    { id: 'connections.prompt-preview', title: 'Prompt previews beneath preset entries', keys: ['prompt preview', 'preset prompt blurb', 'prompt list description', 'prompt comment', 'preview macros'], sources: ['public/scripts/prompt-preview.js', 'public/scripts/PromptManager.js'], anchors: ['TRIM_MACRO_PATTERN', 'prompt-preview'],
        content: 'In Fine-tuning → Presets → Prompts, text entries show a short preview beneath their names and the same text in a tooltip. If the first {{// comment}} has text it supplies the blurb; otherwise the opening prompt text is used. The preview is capped at 140 characters and simplifies whitespace and basic formatting. Comments and {{trim}} markers are removed from the fallback. Previewing does not execute macros or variable setters, change the prompt, enable an entry or make a model request. Open the entry to edit its actual text; the blurb is not the complete prompt sent to a model.' },
    { id: 'connections.pinned-prompts', title: 'Pinned prompt switches beside the desktop chat', keys: ['Pinned prompts', 'Pin prompt to chat', 'Unpin prompt', 'Collapse pinned prompts', 'desktop prompt switches'], sources: ['public/scripts/PromptManager.js', 'public/scripts/neconyan-chat-widgets.js', 'public/scripts/pinned-prompt-toggles.js'], anchors: ['Pinned prompts', 'Collapse pinned prompts', 'neconyan_pinned_prompts'],
        content: 'With a Chat Completion connection, open Fine-tuning → Presets → Prompts and press Pin beside a prompt. Pinned prompts appears beside or above an open Roleplay chat on desktop, following the preset\'s prompt order. Its switches change the same enabled state as the prompt list; pinning alone does not enable a prompt or change its text. Pins are saved with the selected preset, so switching presets changes the list. Collapse pinned prompts keeps a compact control; Unpin in the prompt list removes a pin, and removing the last removes the panel. Phones can manage pins in the prompt list but do not show the chat-side panel. Conversation, Story Mode, Meower and Text Completion do not show it. Using a switch makes no model request.' },
    { id: 'generation.context', title: 'Context limits, reply length and thinking-only responses', keys: ['context size', 'context limit', 'maximum tokens', 'reply length', 'truncated reply', 'out of context', 'Max Response Length', 'ran out of Max Response Length', 'runs out of Max Response Length', 'thinking but no reply text', 'finished reasoning but returned no reply text', 'partial prose'], covers: ['core:generation'], sources: [openai, 'public/script.js', 'public/scripts/generation-request-controls.js', 'src/generation/reasoning-only-result.js'], anchors: ['The reply ran out of Max Response Length while the model was still reasoning. Raise Max Response Length or lower the reasoning effort, then try again.', 'The provider reached its output limit after returning thinking but no reply text. Automatic agents were not run.'],
        content: 'Context is the total input/output allowance supported by the selected model. Character text, history, lore, notes, tools and memory all consume input space. The reply/output limit reserves room for generated text; raising it can leave less room for history. Tokens are not words. Do not set a limit above the provider\'s supported value merely to remove an error. Helper requests carry their own output limit and no longer change your saved reply length. When a reply hits Max Response Length, Neconyan keeps unfinished sentences and partial prose after inline thinking instead of trimming them away. If the output budget runs out while the model is still reasoning (or the model returns thinking with no reply text), the thinking is preserved, automatic after-reply Agents do not run on it, and a warning suggests raising Max Response Length or lowering the reasoning effort.' },
    { id: 'generation.sampling', title: 'Temperature and sampling controls', keys: ['temperature', 'top p', 'top k', 'min p', 'repetition penalty', 'sampling', 'samplers'], sources: ['public/scripts/openai-model-capabilities.js', openai, html],
        content: 'Sampling controls influence which possible text the model selects. Temperature changes variation; top-p/top-k/min-p restrict candidate choices where supported. Repetition-related penalties discourage certain repeats but can damage prose if excessive. Available fields and valid ranges depend on the connection/model. Change a small number at a time and compare replies; a visible unsupported parameter may be ignored or rejected by the provider. No preset guarantees factual accuracy.' },
    { id: 'generation.streaming', title: 'Streaming, reasoning and stop strings', keys: ['streaming', 'reasoning', 'thinking', 'stop strings', 'multiple replies', 'function calling'], sources: [openai, 'public/scripts/reasoning.js', 'public/scripts/tool-calling.js', 'public/scripts/chat-input-capabilities.js'],
        content: 'Streaming displays output as it arrives; disabling it waits for the completed response. Reasoning controls and visibility depend on provider/model support and do not expose every model\'s internal process. Stop strings end generation when matched and can cause unexpectedly short replies. Multiple-response and function-calling support vary by route; the OpenAI (Responses) source is not on the function-calling list, so it does not supply the normal assistant function tools. Automatic product-help reference text does not require function calling.' },
    { id: 'generation.tool-reasoning', title: 'Interleaved Thinking for tool calls', keys: ['Interleaved Thinking', 'Active Tool Chain', 'Since Last User Message', 'tool call reasoning', 'tool-chain thinking', 'Custom interleaved reasoning'],
        sources: [html, openai, 'public/scripts/chat-input-capabilities.js', 'src/generation/roleplay-prompt.js'], anchors: ['Interleaved Thinking', 'Active Tool Chain', 'supportsInterleavedToolReasoning', 'calls.find(call => call.reasoning)?.reasoning'],
        content: 'In Connections, with a Chat Completion source, Advanced & Reasoning has Interleaved Thinking for the Custom (OpenAI-compatible) and OpenRouter sources. It sends reasoning from earlier assistant turns with tool-call requests so a tool chain keeps its thinking context. Choose Disabled, Since Last User Message or Active Tool Chain. It requires Request model reasoning to be on; otherwise the control is disabled. Each tool call keeps its own saved reasoning, and Neconyan falls back to an earlier assistant message only when that call has none. Custom OpenAI-compatible endpoints forward this reasoning in both browser and server replies, as OpenRouter already did. It is off by default, and the provider must accept reasoning in tool-call messages. The setting does not make a model request by itself, and forwarded reasoning can use prompt tokens.' },
    { id: 'generation.reasoning-effort', title: 'Reasoning effort quick switch and model support', keys: ['Reasoning Effort', 'reasoning effort button', 'thinking level', 'brain button', 'change effort quickly', 'supported reasoning efforts', 'model does not expose an effort setting', 'model does not expose a Reasoning Effort setting', 'None unavailable in Reasoning Effort', 'Reasoning cannot be disabled for this model', 'mandatory reasoning'], sources: ['public/scripts/neconyan-tabs.js', 'public/scripts/neconyan-reasoning-effort.js', 'public/scripts/chat-reasoning-capabilities.js', 'public/scripts/generation-request-controls.js', openai, html], anchors: ['Reasoning Effort', 'This model does not expose an effort setting. Your saved choice is kept for other models.', 'Reasoning cannot be disabled for this model. Choose another model to turn it off.', 'deepseek-v4-flash', 'DeepSeek documents none, low, high and max'],
        content: 'Connections and the bottom chat bar\'s brain button (Low, Med, High, XHigh, Max, Min or None) filter Reasoning Effort options to the levels the selected model supports across NanoGPT, OpenRouter and documented native providers (including OpenAI, Google AI Studio, Vertex AI, DeepSeek, Moonshot, Z.AI, MiniMax, MistralAI, Groq, AI/ML API and Fireworks). On native DeepSeek without a reverse proxy, an explicit None turns thinking off for DeepSeek v4 Pro and DeepSeek Flash, and the reply-length controls treat the reply as non-reasoning. DeepSeek Flash offers only None, Low, High and Maximum; Minimum, Medium and Extra High are refused before sending. With no effort sent, DeepSeek Flash still thinks, so the reply keeps its reasoning room. Through a reverse proxy None is not sent, so DeepSeek\'s default applies. When a model does not expose an effort setting, the Connections dropdown is disabled and the bottom-bar brain button is hidden, while your saved choice is kept for other models. When a model requires reasoning (mandatory reasoning), None is unavailable and cannot be chosen. If your saved effort is not supported by the current model, the button shows a warning icon until you pick one of its supported levels. Changing the effort sends no model request by itself.' },
    { id: 'generation.kimi-prefill', title: 'Kimi K3 and K3.1 Pro Partial Prefill', keys: ['Partial Prefill', 'Kimi K3', 'Kimi K3.1 Pro', 'kimi-k3.1-pro', 'kimi-k3.1-pro-highspeed', 'kimi prefill', 'partial: true', 'prefill'], sources: [html, openai, 'public/scripts/extensions/in-chat-agents/agent-runner.js'], anchors: ['Partial Prefill', 'This sends a partial prefill with the parameter \'partial: true\' for Kimi K3 and K3.1 Pro.'],
        content: 'Partial Prefill appears in Chat Completion settings for the Custom, Moonshot, NanoGPT and OpenRouter sources. Text written there is sent as the start of the reply with the parameter \'partial: true\' for Kimi K3 and K3.1 Pro; other models may reject or ignore it. A prefill the model echoes back is not added twice, and rewrite agents that run after the reply are protected from deleting it. Leave the box empty for other models.' },
    { id: 'settings.writing', title: 'Chat & Writing settings', keys: ['Chat & Writing', 'auto continue', 'auto swipe', 'autocomplete', 'message handling', 'Fine-tuning', 'Chat & messages', 'Open keyboard when a chat opens'], covers: ['settings:chat-writing'], sources: [html, 'public/scripts/neconyan-settings-tabs.js'], anchors: ['Open keyboard when a chat opens'],
        content: 'Settings → Chat & Writing has five sections: Chat & messages (sending, streaming, the chat window and message display, including Open keyboard when a chat opens to focus the message box when opening or switching to a chat), Characters (character list, importing and character prompts), Auto-swipe & auto-continue, Autocomplete, and Fine-tuning (Reload, Clean-Up, Debug Menu, prompt context depths and developer options including the STscript parser flags). Each switch has a one-line description under its name. Movable panels and its layout presets sit in Settings → Appearance. Automatic generation options can create additional requests; inspect their conditions and limits before enabling them. Composer autocomplete is separate from a model writing a reply. These general Roleplay settings do not replace Conversation\'s thread-specific behaviour controls.' },
    { id: 'settings.miso-guide', title: 'Miso\'s Help me choose settings guide', keys: ['Miso settings guide', 'settings guide', 'Help me choose settings', 'Help me choose for settings', 'four short questions', 'four settings questions', 'Miso suggests settings', 'settings suggestions', 'suggest settings for me', 'pick settings for me', 'sends no model request', 'Change answers', 'Miso asks you decide settings'], sources: ['public/scripts/miso-settings-recommendations.js', 'public/scripts/miso-settings-guide.js', 'public/scripts/neconyan-settings-tabs.js'], anchors: ['Miso asks, you decide', 'NeconyanMisoSettingsGuide.v1', 'Only the boxes you tick are applied.'],
        content: 'Miso\'s Help me choose button sits beside Find a setting in Settings, on every settings tab. Four short questions cover how the screen feels, how you read, chatting conveniences and this device. Miso reads the settings already on the page and suggests concrete values, including Simple Mode, compact layout, chat style, font size, message details, reply location, sound and low-memory mode. It sends no model request. Results show each setting\'s target, why and where it lives. Tick only what you want, then Apply. Settings already at the suggested value are marked Already set and cannot be ticked. Undo returns the applied settings, but it is blocked if one of them changed elsewhere first. Answers are saved to the account, so reopening the guide shows the last results; Change answers returns to the questions with your saved answers still ticked, and Use my last answers goes straight back to the results. Low-memory mode is saved per browser on this device. The guide does not change your theme or colours. The Agents page has a separate Help me choose for agent recommendations.' },
    { id: 'settings.device', title: 'Phone, streaming and low-memory settings', keys: ['System & Device', 'phone keyboard', 'mobile streaming', 'iOS streaming', 'Android streaming', 'low memory', 'Low-memory mode', 'Use automatic recommendations', 'Memory and performance', 'Stay open in the background', 'tab reloads', 'keep tab open'], covers: ['settings:system-device'], sources: [html, 'public/scripts/neconyan-settings-tabs.js', 'public/scripts/low-memory-mode.js', 'public/scripts/power-user.js', 'public/scripts/background-keep-alive.js'], anchors: ['Low-memory mode', 'Use automatic recommendations', 'Reopen the chat to apply its new message limit.', 'Stay open in the background'],
        content: 'Settings → System & Device groups Import & Restore, desktop/mobile layout, iOS and Android streaming, Memory and performance and message-unloading options. Low-memory mode (saved per browser or device) offers Auto, On and Off. Auto activates when the browser reports 2 GB of memory or less, or the Android app reports a low-RAM device or 3 GiB of total memory or less. When active, it turns on No Blur Effect and keeps 25 messages rendered in Roleplay and Conversation (instead of 200 in Conversation). Any of those settings you changed yourself is kept until you press Use automatic recommendations. Changing the Roleplay limit while a chat is open shows Reopen the chat to apply its new message limit. These options reduce rendering work without changing the model\'s context limit. In Android browsers (not the APK) Leaving the tab has Stay open in the background, off by default and saved per device: while Neconyan is hidden it plays an inaudible looping sound so the browser treats it as a media player instead of unloading it. It uses more battery, shows a media notification, can pause music in other apps and stops when you return or press pause in that notification.' },
    { id: 'settings.background-memory', title: 'Save memory in the background', keys: ['Save memory in the background', 'background memory saving', 'release older off-screen messages', 'Memory and performance', 'restore reading position', 'memory saver'],
        sources: ['public/index.html', 'public/scripts/background-memory-saver.js', 'public/scripts/power-user.js'], anchors: ['Save memory in the background', 'Release reusable caches and older off-screen chat messages when you switch away.', 'Active replies and edits are kept.'],
        content: 'Settings → System & Device → Memory and performance has Save memory in the background, off by default and saved for this device. When on, switching away from Neconyan releases reusable caches and older off-screen Roleplay messages; returning restores them and your reading position. Unsent drafts, unfinished edits and interactive messages are protected, and an active reply, Agent run or message edit prevents chat trimming. Conversation mode does not use the Roleplay message trimming, though reusable token-count caches can still be released. Android and iPhone background notifications use the same cleanup, and the local server releases read-only caches when memory runs low. It reduces memory use without deleting saved chat; it does not guarantee that the operating system will never close the app.' },
    { id: 'settings.phone-composer', title: 'Phone composer, iOS keyboard and Movable panels', keys: ['iPhone composer behind keyboard', 'iPhone composer hidden', 'empty band above keyboard', 'iOS keyboard composer', 'keyboard covers composer', 'composer under keyboard', 'iOS composer gap', 'phone composer visible area', 'Android composer after app switching', 'Movable panels iPhone composer', 'MovingUI iPhone composer', 'iPhone composer height with Movable panels', 'composer gap after app switch', 'home bar composer'],
        sources: [html, 'public/css/neconyan-mobile-shell.css', 'public/scripts/neconyan-tabs.js'], anchors: ['Movable panels', 'Open keyboard when a chat opens', '--sb-ios-shell-height', 'body:not(.movingUI) #sheld', 'body.neconyan:not(:where(.safari)) #sheld', 'Neconyan: iOS 17 WebKit can misresolve dvh'],
        content: 'On Android and other non-Safari phone browsers, the shell follows the visible browser area, so the composer stays above the keyboard and returns after app switching. Movable panels (MovingUI) is on by default; on iPhone, Safari keeps the full-height layout. With Movable panels off on iPhone, the shell ends at the bottom of the visible area, which fixes an empty band above the keyboard. iPhone Home Screen installations reserve the home-bar space once, in the composer, so it is not added twice. This is layout only: Open keyboard when a chat opens is a separate setting, and no option here makes an unusable connection work.' },
    { id: 'recovery.replies', title: 'Recovering a reply after disconnection or a stalled stream', keys: ['lost reply', 'disconnected', 'recover generation', 'background reply', 'server restart', 'closed the page', 'stalled stream', 'connection ended before this reply finished', 'saved reply recovery', 'completed reply after restart', 'Mewmory reply recovery', 'interrupted after provider result', 'never cancel a running reply', 'cancel a running held reply', 'resumable registry is full', 'evict running held reply'], covers: ['core:recovery'], sources: ['src/jobs/store.js', 'public/scripts/neconyan-conversation/roleplay-workflows.js', 'public/scripts/group-chats.js', 'src/resumable-generations.js', 'src/generation/roleplay-prompt-proof.js', 'src/generation/roleplay-execution.js', 'public/script.js', 'public/scripts/generation-outcome-ui.js'], anchors: ['The result from the AI service is unknown after a restart. Retry only if the earlier request did not go through.', 'The connection ended before this reply finished, so it may be incomplete. Automatic agents were not run.', 'Too many live resumable generations; serving this request without resume support', 'memoryPresentation', 'roleplayPromptContentHash'],
        content: 'Ordinary Roleplay and group replies are browser-first. Supported single-character requests carry chat context, so a reopened chat saves the held reply without resending. A server restart loses those browser-held replies, and after-reply Agents are not replayed after the browser closes. A stalled or early-ended stream keeps its partial text or thinking, is marked \'The connection ended before this reply finished, so it may be incomplete. Automatic agents were not run.\', and leaves a fuller server-held copy. Running held requests stop after an hour; finished replies wait 15 minutes, or 24 hours with chat context. A full registry never cancels a running held reply to make room; it evicts only finished or cancelled work. Server jobs cover Conversation, Meower, Labs, protected Roleplay replacements and scoped Notebook context: closing the page does not stop them, reopening reattaches, and Stop asks the server to cancel. After a restart, saved provider results continue; a Roleplay job with a saved main result can finish during an optional helper without repeating it. A completed Mewmory-prepared reply interrupted after the provider result also finishes from saved prompt evidence; changed evidence refuses recovery. An unfinished main request is marked unknown and never resent.' },
    { id: 'recovery.startup-failure', title: 'Fatal startup failure panel and readable errors', keys: ['Neconyan could not finish loading', 'Retry startup', 'startup error', 'Read report', 'POST /api/settings/get failed', 'startup failure panel', 'startup loop', 'reload loop', 'Clear frontend cache and reload'], sources: ['public/script.js', 'public/scripts/neconyan-boot-guard.js', 'docs/crash-diagnostics.md'], anchors: ['Neconyan could not finish loading', 'Retry startup', 'Startup error details', 'Read report', 'POST /api/settings/get failed (HTTP ', 'showStartupFailure', 'Clear frontend cache and reload'],
        content: 'When a later startup step fails after the page has loaded its modules, Neconyan shows a fatal startup panel instead of a toast or repeated reloads. Startup error details names the failure, for example POST /api/settings/get failed (HTTP 500), and the panel offers Retry startup and Read report. Retry startup reloads the page; saved data is not cleared. Read report opens the saved browser report when the crash reader is available. The separate nonfatal panel for WebKit module or cache failures still offers Clear frontend cache and reload and Continue anyway. Repeated automatic reloads on a settings failure are gone. If Retry returns the same error, read the report and check the server first; the panel does not claim your chats or settings were damaged.' },
    { id: 'recovery.retained-replies', title: 'Saved replies from the previous version', keys: ['Recovered reply disappeared', 'old Recovered reply', 'reply from previous version', '1.3.4.1 saved reply', 'retained reply', 'old reply after update', 'automatic reply upgrade', 'old recovered reply conflict', 'old recovered reply restore button'], sources: ['src/jobs/store.js'], anchors: ['retainedReplyUpgrade', 'retainedReply', 'ROLEPLAY_REPLY_PRESERVED', 'SAFE_START', 'The finished reply from the previous version was kept in job history, but its saved model result is missing, so it was not sent again.', 'Another step of this saved reply needs recovery, so the finished reply was kept in job history and was not written to the chat.'],
        content: 'Version 1.3.4.1 kept finished replies that couldn\'t be added to their chat in the Recovered reply card. The first normal start after updating handles those old copies automatically: Neconyan protects the saved copy before routine job cleanup can remove it, checks that the chat still matches, and saves the reply once using the already-paid result. It doesn\'t ask the main model again and doesn\'t show a second recovery card or a restore button. If the chat changed since that reply, or its saved model result is missing or doesn\'t match, the old copy stays in job history instead of overwriting your edit. Nothing is sent again. Replies you cancelled or dismissed yourself stay that way, and safe mode waits until you start normally. A completed upgrade is not repeated on later restarts.' },
    { id: 'recovery.exports', title: 'Chat exports, account backups and imports', keys: ['backup', 'export chat', 'import chat', 'JSONL', 'Import & Restore', 'full setup import'], covers: ['core:transfers'], sources: ['src/operations/account-backup.js', 'src/users.js', 'public/scripts/neconyan-tabs.js', html],
        content: 'Use the chat\'s export/import actions for conversation files; JSONL stores one record per line. Character, lorebook, persona, preset and agent exports have different scopes. Settings → System & Device → Import & Restore lets you choose chats, personas, character cards and lorebooks separately from a SillyTavern or SillyBunny folder path or backup ZIP. All four are selected by default. Chats include groups and attachments; lorebooks includes native books and saved history. Matching files in selected libraries are replaced; other preferences, keys, presets, themes and bookkeeping are not imported. Unselected library files, other deliberate exclusions and damaged files appear in separate report sections before reloading. Sync Extensions is separate. Keep a backup first. Chat Archive organisation and Time Machine snapshots are not whole-account backups. Main secrets are excluded from account backups unless the server allows key exposure; inspect exports before sharing.' },
    { id: 'recovery.account-jobs', title: 'Backups, imports and resets that survive closing the page', keys: ['Download Backup', 'saved account backup', 'backup still running', 'import stopped', 'saved account import', 'Reset Everything', 'reset code'], sources: ['public/scripts/account-data.js', 'public/scripts/account-import.js', 'public/scripts/user.js', 'public/scripts/templates/userReset.html'], anchors: ['The accepted backup will continue if this page closes.', 'Choose a saved account backup', 'Choose a saved account import', 'Account reset code has been posted to the server console.'],
        content: 'Download Backup, Import & Restore and Reset Everything run as saved server operations: closing the page does not stop accepted work. Your chat and settings are saved first. Reopen Settings → Cache & Account → Account Settings → Account to pick from Choose a saved account backup (then Download saved backup or Stop backup) or Choose a saved account reset (then Reload reset account); Import & Restore lists Choose a saved account import with Stop import and Reload imported account. A ZIP import may ask you to select the original ZIP again. Reset Everything needs your current password and a code posted to the server console, so ask the administrator; it cannot be undone. None of these costs model requests.' },
    { id: 'recovery.clean-up', title: 'Clean-Up (Data Maid)', keys: ['Clean-Up', 'Data Maid', 'delete unused files', 'free disk space', 'orphaned chats', 'old backups'], sources: [html, 'public/scripts/data-maid.js', 'public/scripts/templates/dataMaidDialog.html'], anchors: ['Clean-Up', 'Once deleted, the files will be gone forever!', 'Choose a saved maintenance report'],
        content: 'Settings → Chat & Writing → Fine-tuning → Tools → Clean-Up opens a dialog that finds files, images, chats and group chats of deleted characters or groups, orphaned thumbnails, and automatic chat and settings backups. Press Scan; the scan runs on the server, and Choose a saved maintenance report reopens an earlier result after closing the dialog. You then delete items or whole categories. Files and Images include manual uploads, and once deleted the files are gone forever, so back up first. It sends no model requests.' },
    { id: 'settings.account', title: 'Account settings, snapshots and cache', keys: ['Cache & Account', 'account profile', 'settings snapshot', 'clear cache', 'reset settings', 'change password'], covers: ['settings:cache-account'], sources: ['public/scripts/templates/userProfile.html', 'public/scripts/neconyan-settings-tabs.js', 'public/script.js'],
        content: 'Settings → Cache & Account holds Account Settings and cache utilities. Account Settings → Account opens the profile, which offers Settings Snapshots, Download Backup and Change Password, plus Reset Settings (settings only, to defaults) and Reset Everything (all user data). Account identity is separate from a chat persona. Clearing cached assets is not the same as deleting server data or resetting settings. Save pending work before a reload/reset and read the confirmation. A failed or conflicting settings save needs resolution; changing the same field repeatedly is not proof the server retained it.' },
    { id: 'privacy.signin', title: 'Sign-in, remembered devices and passkeys', keys: ['sign in', 'login', 'remember device', 'passkey', 'authentication', 'session expired'], covers: ['core:accounts'], sources: ['public/login.html', 'src/endpoints/auth.js', 'src/middleware/sessionAuth.js', html], anchors: ['Remember this device for 30 days', 'Sign in with a passkey', 'Adding a passkey needs HTTPS and a browser that supports passkeys.'],
        content: 'Browser authentication uses Neconyan\'s sign-in page when configured. Remember this device for 30 days is opt-in and uses an expiring server-validated session; clearing browser storage or changing credentials can require sign-in again. Passkeys are added under Settings → Cache & Account → Account Settings → Passkeys with a name and your workspace password; adding one needs HTTPS and a supporting browser, and a passkey works only at the server address it was added on. Then use Sign in with a passkey. Otherwise contact the administrator; do not expect an HTTP Basic browser popup.' },
    { id: 'troubleshooting.browser-session', title: 'Invalid CSRF token and two local installations', keys: ['Invalid CSRF token', 'CSRF', 'two installations', 'two copies', 'different ports', 'browser session collision'], sources: ['src/users.js', 'src/server-main.js', 'public/scripts/csrf-token-refresh.js'], anchors: ['getCookieSessionName', 'cookieSessionName', 'Invalid CSRF token'],
        content: 'Invalid CSRF token means the browser request did not match its current session token, a check that protects requests made through your signed-in session. Reload the page and sign in again if asked. Protected chat requests refresh this token and retry once automatically, so a logged rejection can be followed by success. Older installations on the same hostname could replace each other\'s session cookie even on different ports. Updated copies give session cookies distinct names for their data folders and configured ports; the upgrade may require signing in again. To isolate an older-copy conflict, stop the other copy, close its tabs and open only the affected installation in a fresh private window. CSRF errors do not establish that chat files are damaged. ROLEPLAY_SOURCE_CHANGED and ROLEPLAY_RECOVERY_REQUIRED concern saved-file tracking and need their own recovery diagnosis; a browser reload does not repair those files.' },
    { id: 'privacy.external', title: 'Private data and external requests', keys: ['privacy', 'offline', 'external media', 'remote requests', 'data storage', 'secrets'], covers: ['core:privacy'], sources: ['PRODUCT.md', 'public/scripts/templates/forbidMedia.html', 'src/endpoints/secrets.js'],
        content: 'Application data is stored on the configured Neconyan server, but remote model calls send their supplied context to the selected provider. Optional image generation, captioning, TTS, translation, card search, fonts and media can make separate external requests. Settings → Chat & Writing → Chat & messages → Messages has Block external media (formerly Forbid External Media). The character or group external-media dialog also has Block external media by default: it changes the global default, while Always allowed or Always forbidden overrides still apply to that character or group. This controls supported embedded-media loading, not all network activity. Outside media sites can see your IP address when loaded. Keep provider keys in credential storage and inspect diagnostics/exports before sharing them. Self-hosted does not mean every enabled feature works offline.' },
    { id: 'admin.operations', title: 'Server status, updates and logs', keys: ['server status', 'update Neconyan', 'restart server', 'logs', 'administrator', 'server configuration', 'data folder', 'install folder', 'where is my data', 'Neconyan folder path'], covers: ['core:administration'], sources: ['public/scripts/neconyan-tabs.js', 'default/config.yaml', 'src/jobs/store.js'], anchors: ['Updates & Restart', 'Update & Restart', 'Restart server', 'Server logs', 'Your data folder', 'Copy Neconyan folder path'],
        content: 'The Server sheet offers Server status, Updates & Restart (Check for updates, Update & Restart, Restart server) and Server logs, subject to administrator permissions. Back up data and configuration before updates. A restart interrupts in-flight requests: saved server jobs resume where safe or are marked interrupted, and page-run replies held in memory are lost. Server status shows the Neconyan folder and Your data folder paths for this installation, each with a copy button. The configuration template documents options; the active configuration may live outside the app folder. Hostnames and service names are deployment-specific, so ask the administrator rather than inventing a shell command. Inspect copied logs for private data.' },
    { id: 'recovery.job-history', title: 'Clearing job history and a full job ledger', keys: ['Clear job history', 'job ledger is full', 'job ledger for this account is full', 'job list', 'failed jobs', 'stuck jobs', 'old jobs piling up'], sources: [html, 'public/scripts/neconyan-settings-tabs.js', 'public/scripts/job-history-cleanup.js', 'src/jobs/store.js'], anchors: ['Clear job history', 'Cache &amp; Storage Utilities', 'Job history was already clear.', 'JOB_FAILURE_RETENTION_MS'],
        content: 'Server workflows, image and memory tasks use saved jobs; ordinary browser-first replies do not. Settings → Cache & Account → Cache & Storage Utilities has Clear job history beside the cache buttons. It asks once, then removes finished and failed jobs from the server\'s job list. Work still running stays, and chats and messages are not touched, but failed replies can no longer be retried afterwards. Use it when sending fails with \'The job ledger for this account is full\'. Neconyan also tidies by itself: a failed job is kept for a day so it can be retried, then cleared, and on restart or when the list is full an old failure makes room so new messages are never refused.' },
    { id: 'troubleshooting.connection', title: 'Diagnosing failed model requests', keys: ['connection failed', '401', '403', '429', 'insufficient credits', 'model not found', 'timeout', 'API error'], covers: ['core:troubleshooting'], sources: [openai, 'public/scripts/textgen-settings.js', 'public/scripts/extensions/shared.js', 'public/scripts/extensions/in-chat-agents/agent-runner.js'],
        content: 'Read the actual provider error and identify which connection made the request: the main reply, Conversation override, agent, memory role or image provider may differ. Authentication failures suggest credentials/permissions; model-not-found errors suggest the selected model or endpoint; rate/credit errors require checking provider limits. A timeout or server error does not prove the provider avoided charging, so Neconyan does not automatically resend such requests. Check context/output limits and retry only after understanding the error. Share redacted error text, never the key.' },
    { id: 'api.conversation', title: 'Conversation HTTP API boundaries', keys: ['REST API', 'HTTP API', 'Conversation API', 'integration'], covers: ['core:api'], sources: ['docs/conversation-mode-rest-api.md', 'src/endpoints/neconyan-conversation.js', 'src/generation/conversation-effects.js', 'src/push-notifications.js'], anchors: ['sendSystemNotification', 'shouldNotifyConversation'],
        content: 'The Conversation HTTP API exposes supported store, group, thread and message operations; /message/send appends a user message, generates one selected character reply and saves both. In a group it does not choose several speakers. Follow the installed REST API reference for routes, authentication and payload formats. The API response is data, not audio. Optional system notifications are delivered separately and can arrive with the page closed when the device has opted in; audio playback still needs the browser page. User-supplied model settings still need valid provider configuration. Ask for the intended operation and installed API documentation rather than inventing an endpoint or bypassing authentication.' },
    { id: 'connections.formatting', title: 'The Formatting workspace and its sections', keys: ['Formatting workspace', 'Context & cleanup', 'Instruct template', 'Reply controls', 'Structured Prefill', 'Formatting reasoning', 'formatting tour'], sources: ['public/scripts/neconyan-tabs.js', html], anchors: ['Context & cleanup', 'Instruct template', 'Reply controls', 'Structured Prefill', 'FormattingReasoning'],
        content: 'Open Formatting from the sidebar\'s Fine-tuning section. It groups controls into Context & cleanup (story layout, spacing and unfinished sentences), Instruct template (message markers for local models), System prompt (instructions before or after chat), Reasoning (recognising, showing and reusing thinking), Reply controls (prefixes, stopping strings and token counting) and Structured Prefill (the starter text a Chat Completion reply begins with, plus presets and an optional starter model). Tour explains the page. Available controls depend on the connection type: Chat Completion prompt lists are managed in its own preset controls, not by assuming an Instruct template applies. Formatting affects how supported requests or replies are prepared; it does not choose an appearance theme or create a model connection.' },
    {
        id: 'connections.structured-prefill', title: 'Structured Prefill patterns, presets and checks', keys: ['Structured Prefill', 'structured prefill format', 'Structured Prefill preset', 'Dialogue first', 'Action first', 'Choose a mood', 'Private scene note', 'Provider schema', 'Instructions best effort', 'Continue overlap', 'Structured Prefill check', '[[keep]]', '[[pg]]', 'sp-preset'],
        sources: [html, 'public/scripts/structured-prefill.js', 'public/scripts/structured-prefill-ui.js', 'src/structured-prefill.js', 'docs/structured-prefill.md'],
        anchors: ['structured-prefill-settings', 'Ready-to-use preset', 'Output method', 'Continue overlap (characters)', 'Prefill presets', 'Provider accepted the request. Reply matches the full pattern.', 'The provider did not return the requested Continue overlap. The saved reply was not changed.'],
        content: 'Fine-tuning → Formatting → Structured Prefill, the last section, is off by default. The Ready-to-use preset list is built in; your saved Prefill presets list starts empty. It turns an assistant prefill or Use a separate starter template into a reply pattern. For a first try, tick Use a separate starter template, put I feel [[opt:calm|curious]]. [[keep]] in Starter template, turn on Use Structured Prefill and send a normal reply. Built-in examples include Dialogue first, Action first, Choose a mood and more; choosing one fills the controls without enabling the feature or adding to saved presets. Provider schema sends a JSON schema and needs provider support; Instructions (best effort) works elsewhere but does not enforce the pattern. Slots include [[words:2-5]], [[line:2]], [[keep]], [[end]] and [[pg]]. [[pg]] uses the saved Starter model profile and adds one request; a failure leaves an empty slot and a warning. Save, export or import named presets under Prefill presets; /sp-preset <name> applies one. Reply matches the full pattern. means Neconyan\'s check passed, not that the provider enforced it; a mismatch keeps the reply. Continue overlap removes a repeated join; a mismatched overlap is refused rather than appended. Text Completion does not use this feature.' },
];
